import 'package:flutter/material.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:flutter_svg/flutter_svg.dart';
import 'package:go_router/go_router.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(
    options: const FirebaseOptions(
      apiKey: "YOUR_API_KEY",
      appId: "YOUR_APP_ID",
      messagingSenderId: "YOUR_SENDER_ID",
      projectId: "YOUR_PROJECT_ID",
      storageBucket: "YOUR_BUCKET.appspot.com",
    ),
  );
  runApp(const MyApp());
}

final GoRouter _router = GoRouter(
  routes: [
    GoRoute(path: '/', builder: (context, state) => const GalleryScreen()),
    GoRoute(
      path: '/session/:id',
      builder: (context, state) => SessionDetailScreen(id: state.pathParameters['id']!),
    ),
  ],
);

class MyApp extends StatelessWidget {
  const MyApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp.router(routerConfig: _router);
}

// === ГЛАВНЫЙ ЭКРАН — СПИСОК СЕССИЙ (динамический) ===
class GalleryScreen extends StatelessWidget {
  const GalleryScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Цифровой Оракул — Галерея')),
      body: StreamBuilder<QuerySnapshot>(
        stream: FirebaseFirestore.instance
            .collection('sessions')
            .orderBy('timestamp', descending: true)
            .snapshots(),
        builder: (context, snapshot) {
          if (snapshot.hasError) return const Center(child: Text('Ошибка'));
          if (!snapshot.hasData) return const Center(child: CircularProgressIndicator());

          final docs = snapshot.data!.docs;
          return ListView.builder(
            itemCount: docs.length,
            itemBuilder: (context, index) {
              final data = docs[index].data() as Map<String, dynamic>;
              final id = docs[index].id;
              return ListTile(
                leading: data['previewUrl'] != null
                    ? Image.network(data['previewUrl'], width: 60, height: 60, fit: BoxFit.cover)
                    : const Icon(Icons.image),
                title: Text(data['title'] ?? 'Сессия $id'),
                subtitle: Text(data['timestamp']?.toDate().toString() ?? ''),
                onTap: () => context.go('/session/$id'),
              );
            },
          );
        },
      ),
    );
  }
}

// === ЭКРАН ОДНОЙ СЕССИИ (то, что показывает QR) ===
class SessionDetailScreen extends StatelessWidget {
  final String id;
  const SessionDetailScreen({super.key, required this.id});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Ваша сессия #$id')),
      body: FutureBuilder<DocumentSnapshot>(
        future: FirebaseFirestore.instance.collection('sessions').doc(id).get(),
        builder: (context, snapshot) {
          if (!snapshot.hasData) return const Center(child: CircularProgressIndicator());
          final data = snapshot.data!.data() as Map<String, dynamic>;

          return SingleChildScrollView(
            padding: const EdgeInsets.all(24),
            child: Column(
              children: [
                if (data['svgUrl'] != null)
                  SvgPicture.network(
                    data['svgUrl'],
                    width: 600,
                    height: 600,
                    placeholderBuilder: (_) => const CircularProgressIndicator(),
                  ),
                const SizedBox(height: 30),
                Text(data['title'] ?? 'Персональный артефакт', style: Theme.of(context).textTheme.headlineMedium),
                // здесь можно добавить другие файлы из сессии
              ],
            ),
          );
        },
      ),
    );
  }
}


Это именно то, что вы просили: StreamBuilder + ListView.builder — автоматически обрабатывает любое количество сессий и обновляется в реальном времени.



