uploader.py (фрагмент):


Python


Копировать


import firebase_admin
from firebase_admin import credentials, firestore, storage
import os
from datetime import datetime

cred = credentials.Certificate("serviceAccountKey.json")
firebase_admin.initialize_app(cred, {
    'storageBucket': 'ваш-проект.appspot.com'
})

db = firestore.client()
bucket = storage.bucket()

def upload_session(session_id: str, svg_path: str, preview_path: str, title: str = None):
    # Загружаем файлы
    svg_blob = bucket.blob(f"sessions/{session_id}/image.svg")
    svg_blob.upload_from_filename(svg_path)
    svg_blob.make_public()
    svg_url = svg_blob.public_url

    preview_blob = bucket.blob(f"sessions/{session_id}/preview.png")
    preview_blob.upload_from_filename(preview_path)
    preview_blob.make_public()
    preview_url = preview_blob.public_url

    # Создаём документ
    doc_ref = db.collection('sessions').document(session_id)
    doc_ref.set({
        'timestamp': datetime.utcnow(),
        'title': title or f"Сессия {session_id}",
        'svgUrl': svg_url,
        'previewUrl': preview_url,
        'status': 'printed'
    })
    print(f"✅ Сессия {session_id} загружена в Firebase")



